// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

/**
 * @title AuthRelay - Cross-chain authentication relay for gRPC bridge
 * @notice Validates NTLM-style challenge-response auth tokens relayed from
 *         off-chain gRPC services before executing privileged operations.
 *         Uses async callback pattern via oracle for challenge verification.
 */
contract AuthRelay {
    using ECDSA for bytes32;
    using MessageHashUtils for bytes32;

    struct AuthSession {
        address initiator;
        bytes32 challengeHash;
        bytes32 responseHash;
        uint256 timestamp;
        uint8 state; // 0=pending, 1=challenged, 2=verified, 3=rejected
        address delegatedTo;
    }

    mapping(bytes32 => AuthSession) public sessions;
    mapping(address => bool) public trustedOracles;
    mapping(address => uint256) public nonces;
    address public admin;
    uint256 public sessionTimeout = 300; // 5 minutes

    event SessionCreated(bytes32 indexed sessionId, address initiator);
    event ChallengeIssued(bytes32 indexed sessionId, bytes32 challengeHash);
    event SessionVerified(bytes32 indexed sessionId, address delegatedTo);
    event PrivilegedAction(bytes32 indexed sessionId, address executor, bytes data);

    modifier onlyAdmin() {
        require(msg.sender == admin, "Not admin");
        _;
    }

    modifier onlyOracle() {
        require(trustedOracles[msg.sender], "Not trusted oracle");
        _;
    }

    constructor(address _oracle) {
        admin = msg.sender;
        trustedOracles[_oracle] = true;
    }

    function addOracle(address _oracle) external onlyAdmin {
        trustedOracles[_oracle] = true;
    }

    function removeOracle(address _oracle) external onlyAdmin {
        trustedOracles[_oracle] = false;
    }

    /**
     * @notice Initiates an auth session (Type 1 - Negotiate)
     * @param targetService The service identifier being authenticated to
     * @return sessionId The unique session identifier
     */
    function initiateSession(bytes32 targetService) external returns (bytes32) {
        uint256 nonce = nonces[msg.sender]++;
        bytes32 sessionId = keccak256(abi.encodePacked(
            msg.sender, targetService, nonce, block.timestamp
        ));

        sessions[sessionId] = AuthSession({
            initiator: msg.sender,
            challengeHash: bytes32(0),
            responseHash: bytes32(0),
            timestamp: block.timestamp,
            state: 0,
            delegatedTo: address(0)
        });

        emit SessionCreated(sessionId, msg.sender);
        return sessionId;
    }

    /**
     * @notice Oracle callback with challenge (Type 2 - Challenge)
     * @dev Called by off-chain gRPC oracle after NTLM negotiation
     */
    function oracleChallenge(
        bytes32 sessionId,
        bytes32 challengeHash
    ) external onlyOracle {
        AuthSession storage session = sessions[sessionId];
        require(session.state == 0, "Invalid state");
        require(block.timestamp - session.timestamp <= sessionTimeout, "Expired");

        session.challengeHash = challengeHash;
        session.state = 1;
        emit ChallengeIssued(sessionId, challengeHash);
    }

    /**
     * @notice Submit authentication response (Type 3 - Authenticate)
     * @param sessionId The session to authenticate
     * @param response The NTLM response hash
     * @param delegateTo Address to delegate privileges to
     */
    function submitResponse(
        bytes32 sessionId,
        bytes32 response,
        address delegateTo
    ) external {
        AuthSession storage session = sessions[sessionId];
        require(session.state == 1, "Not in challenge state");
        require(msg.sender == session.initiator, "Not session owner");
        require(block.timestamp - session.timestamp <= sessionTimeout, "Expired");

        session.responseHash = response;
        session.delegatedTo = delegateTo;
        // State remains 1 until oracle verifies
        // This is the async callback pattern
    }

    /**
     * @notice Oracle verifies the response against NTLM backend
     * @dev The relay vulnerability: oracle validates response but the
     *      delegatedTo field can be set to ANY address by the initiator,
     *      effectively relaying authenticated credentials to an attacker.
     */
    function oracleVerify(
        bytes32 sessionId,
        bool isValid
    ) external onlyOracle {
        AuthSession storage session = sessions[sessionId];
        require(session.state == 1, "Not in challenge state");
        require(session.responseHash != bytes32(0), "No response submitted");

        if (isValid) {
            session.state = 2;
            emit SessionVerified(sessionId, session.delegatedTo);
        } else {
            session.state = 3;
        }
    }

    /**
     * @notice Execute privileged action using verified session
     * @dev Both initiator AND delegatedTo can execute
     */
    function executePrivileged(
        bytes32 sessionId,
        address target,
        bytes calldata data
    ) external returns (bool, bytes memory) {
        AuthSession storage session = sessions[sessionId];
        require(session.state == 2, "Session not verified");
        require(
            msg.sender == session.initiator || msg.sender == session.delegatedTo,
            "Not authorized"
        );
        require(block.timestamp - session.timestamp <= sessionTimeout, "Expired");

        emit PrivilegedAction(sessionId, msg.sender, data);
        (bool success, bytes memory result) = target.call(data);
        return (success, result);
    }

    /**
     * @notice Update delegation after verification (allows relay attack)
     * @param sessionId The verified session
     * @param newDelegate New address to delegate to
     */
    function updateDelegation(
        bytes32 sessionId,
        address newDelegate
    ) external {
        AuthSession storage session = sessions[sessionId];
        require(session.state == 2, "Session not verified");
        require(msg.sender == session.initiator, "Not session owner");
        session.delegatedTo = newDelegate;
    }

    /**
     * @notice Revoke a session
     */
    function revokeSession(bytes32 sessionId) external {
        AuthSession storage session = sessions[sessionId];
        require(
            msg.sender == session.initiator || msg.sender == admin,
            "Not authorized"
        );
        session.state = 3;
    }
}
